import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  const weatherSchema = {
    type: 'object',
    properties: {location: {type: 'string'}},
    required: ['location'],
  };

  const registerWeather = (registry: ToolRegistry, executor: Parameters<ToolRegistry['register']>[1]): void => {
    registry.register({name: 'weather', description: 'Get weather', inputSchema: weatherSchema}, executor);
  };

  const countCompiles = (registry: ToolRegistry): {get: () => number} => {
    let compileCalls = 0;
    const ajv = (
      registry as unknown as {
        ajv: {compile: (inputSchema: Record<string, unknown>) => unknown};
      }
    ).ajv;
    const originalCompile = ajv.compile.bind(ajv);
    ajv.compile = inputSchema => {
      compileCalls += 1;
      return originalCompile(inputSchema);
    };
    return {get: () => compileCalls};
  };

  it('rejects input missing a required property without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'city_forecast',
        description: 'Get a forecast for a city',
        inputSchema: {
          type: 'object',
          properties: {city: {type: 'string'}},
          required: ['city'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'clear';
      }
    );

    const response = await registry.execute('city_forecast', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringContaining('city'),
    });
  });

  it('rejects a wrong-typed nested property with a redacted path-aware message', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'lookup_profile',
        description: 'Look up a profile by display name',
        inputSchema: {
          type: 'object',
          properties: {
            profile: {
              type: 'object',
              properties: {displayName: {type: 'string'}},
              required: ['displayName'],
            },
          },
          required: ['profile'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_profile', {profile: {displayName: 987654321}});

    expect({
      executorCalls,
      result: response.result,
      leaksValue: response.result.includes('987654321'),
    }).toEqual({
      executorCalls: 0,
      result: '/profile/displayName must be string',
      leaksValue: false,
    });
  });

  it('passes valid input with extra properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', requestedBy: 'Ada'};
    const executor = jest.fn(async (_input: Record<string, unknown>) => 'clear');

    registerWeather(registry, executor);

    await registry.execute('weather', input);

    const calls = executor.mock.calls;
    expect({calls: calls.length, received: calls[0]?.[0]}).toEqual({
      calls: 1,
      received: input,
    });
  });

  it('compiles a function-source schema once when the same schema object is reused', async () => {
    const registry = new ToolRegistry();
    const schema = weatherSchema;
    const compileCounter = countCompiles(registry);

    registry.register(
      () => ({name: 'weather', description: 'Get weather', inputSchema: schema}),
      async () => 'clear'
    );

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('weather', {location: 'Paris'});
    }

    expect(compileCounter.get()).toBe(1);
  });

  it('validates function-source input against the schema returned for each call', async () => {
    const registry = new ToolRegistry();
    let useLocationSchema = true;
    const executor = jest.fn(async () => 'clear');

    registry.register(
      () => ({
        name: 'weather',
        description: 'Get weather',
        inputSchema: useLocationSchema
          ? {type: 'object', properties: {location: {type: 'string'}}, required: ['location']}
          : {type: 'object', properties: {city: {type: 'string'}}, required: ['city']},
      }),
      executor
    );

    const firstResponse = await registry.execute('weather', {location: 'Paris'});
    useLocationSchema = false;
    const secondResponse = await registry.execute('weather', {location: 'Paris'});
    const executorCallCount = executor.mock.calls.length;

    expect({
      firstResult: firstResponse.result,
      secondResult: secondResponse.result,
      executorCalls: executorCallCount,
    }).toEqual({
      firstResult: 'clear',
      secondResult: expect.stringContaining('city'),
      executorCalls: 1,
    });
  });

  it('compiles a static schema once across repeated executions', async () => {
    const registry = new ToolRegistry();
    const compileCounter = countCompiles(registry);

    registerWeather(registry, async () => 'clear');

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('weather', {location: 'Paris'});
    }

    expect(compileCounter.get()).toBe(1);
  });

  it('throws the unchanged unknown-tool error', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_weather', {})).rejects.toThrow('Unknown tool: missing_weather');
  });
});
import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validators = new WeakMap<object, ValidateFunction>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const compiled = typeof definition === 'function' ? undefined : this.compile(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator: compiled});
  }

  private compile(definition: ToolDefinition): ValidateFunction {
    try {
      return this.ajv.compile(definition.inputSchema);
    } catch (error) {
      throw new Error(
        `Unable to compile inputSchema for tool ${definition.name}: ${error instanceof Error ? error.message : String(error)}`,
        {cause: error}
      );
    }
  }

  private validatorFor(definition: ToolDefinition): ValidateFunction {
    const schema = definition.inputSchema;
    const cached = this.validators.get(schema);
    if (cached) return cached;
    const validator = this.compile(definition);
    this.validators.set(schema, validator);
    return validator;
  }

  private normalizeInstancePath(instancePath?: string): string | undefined {
    if (!instancePath?.startsWith('.')) return instancePath;
    return instancePath
      .split('.')
      .filter(Boolean)
      .map(property => `/${property}`)
      .join('');
  }

  private validationMessage(validator: ValidateFunction): string {
    const error = validator.errors?.[0] as
      | {
          instancePath?: string;
          keyword: string;
          params: {missingProperty?: unknown; type?: unknown};
          schemaPath?: string;
        }
      | undefined;
    if (!error) return 'Tool input does not match the registered inputSchema';
    const schemaPath = error.schemaPath ?? '';
    const schemaProperties = [...schemaPath.matchAll(/\/properties\/([^/]+)/g)].map(match => match[1]);
    const instancePath = error.instancePath ?? (error as {dataPath?: string}).dataPath;
    const normalizedPath = this.normalizeInstancePath(instancePath);
    const path = normalizedPath || (schemaProperties.length > 0 ? `/${schemaProperties.join('/')}` : '(input)');
    if (error.keyword === 'required') {
      return `${path} must have required property ${String(error.params.missingProperty)}`;
    }
    if (error.keyword === 'type') {
      return `${path || '(input)'} must be ${String(error.params.type)}`;
    }
    return `${path || '(input)'} violates ${error.keyword}`;
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Executes a registered tool after validating input against its schema; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = tool.validator ?? this.validatorFor(definition);
    if (!validator(input)) {
      const result = this.validationMessage(validator);
      log.warn('tool', 'input rejected', {name, result});
      return {result};
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
